using System;

namespace Orleans.Transactions.TestKit.Consistency
{
    /// <summary>
    /// Configures randomized transactions generated by the consistency test grains.
    /// </summary>
    [Serializable]
    [GenerateSerializer]
    public class ConsistencyTestOptions
    {
        /// <summary>
        /// Gets or sets the seed used to generate repeatable test operations.
        /// </summary>
        [Id(0)]
        public int RandomSeed { get; set; } = 0;

        /// <summary>
        /// Gets or sets the number of grains participating in the test.
        /// </summary>
        [Id(1)]
        public int NumGrains { get; set; } = 50;

        /// <summary>
        /// Gets or sets the maximum nested grain call depth.
        /// </summary>
        [Id(2)]
        public int MaxDepth { get; set; } = 5;

        /// <summary>
        /// Gets or sets a value indicating whether nested grain calls are ordered to avoid deadlocks.
        /// </summary>
        [Id(3)]
        public bool AvoidDeadlocks { get; set; } = true;

        /// <summary>
        /// Gets or sets a value indicating whether nested call scheduling stops before the transaction timeout.
        /// </summary>
        [Id(4)]
        public bool AvoidTimeouts { get; set; } = true;

        /// <summary>
        /// Gets or sets how the test determines whether each operation reads or writes state.
        /// </summary>
        [Id(5)]
        public ReadWriteDetermination ReadWrite { get; set; } = ReadWriteDetermination.PerGrain;

        /// <summary>
        /// Gets or sets the base grain key added to each logical grain number.
        /// </summary>
        [Id(6)]
        public long GrainOffset { get; set; }

        /// <summary>
        /// The exclusive upper bound on the number of grains in a consistency test.
        /// </summary>
        public const int MaxGrains = 100000;
    }

    /// <summary>
    /// Specifies the scope at which randomized consistency tests select read or write operations.
    /// </summary>
    public enum ReadWriteDetermination
    {
        /// <summary>
        /// Selects one operation kind for all accesses in a transaction.
        /// </summary>
        PerTransaction,

        /// <summary>
        /// Selects one operation kind for each grain accessed by a transaction.
        /// </summary>
        PerGrain,

        /// <summary>
        /// Selects an operation kind independently for each grain access.
        /// </summary>
        PerAccess
    }
}
